#!/usr/bin/env bash
set -euo pipefail

RPC="http://65.109.127.109:8080"
PK="0x2a871d0798f97d79848a013d4936a73bf4cc922c825d33c1cf7073dff6d409c6"
FROM="0xa0Ee7A142d267C1f36714E4a8F75612F20a79720"

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CACHE_FILE="$SCRIPT_DIR/.check-mip8.tmp"

# Creation bytecode of: a uint256[200] array with setMany() writing all 200 slots
BYTECODE=""

CONTRACT=""
if [ -f "$CACHE_FILE" ]; then
  CACHED_ADDR=$(cat "$CACHE_FILE")
  CODE=$(cast code "$CACHED_ADDR" --rpc-url "$RPC" 2>/dev/null || echo "0x")
  if [ -n "$CACHED_ADDR" ] && [ "$CODE" != "0x" ]; then
    CONTRACT="$CACHED_ADDR"
  fi
fi

if [ -z "$CONTRACT" ]; then
  CONTRACT=$(cast send --rpc-url "$RPC" --private-key "$PK" --create "$BYTECODE" --json | jq -r .contractAddress)
  echo "$CONTRACT" > "$CACHE_FILE"
fi

KEYCOUNT=$(cast access-list "$CONTRACT" "setMany()" --from "$FROM" --rpc-url "$RPC" | grep -c '^ *0x')

if [ "$KEYCOUNT" -gt 0 ] && [ "$KEYCOUNT" -le 2 ]; then
  echo "MIP-8-activated"
else
  echo "MIP-8-not-active ($KEYCOUNT keys)"
fi
